def compute(vars):
    initial_rate = vars["v1"]
    ultimate_rate = vars["v2"]
    difference = initial_rate - ultimate_rate
    return {
        "value": difference,
        "trace": {
            "initial_rate": initial_rate,
            "ultimate_rate": ultimate_rate,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
